"""The sweeper's rules on a pretend fleet. Times are hours since Monday 09:00."""
H = 1.0

def sweep(now, vms):
    for vm in vms:
        if vm["state"] == "terminated":
            continue
        tags = vm["tags"]
        if "run-id" in tags and tags["lease-until"] < now:
            act(now, vm, "terminate", "lease expired: no live run owns this VM")
        elif vm["state"] == "stopped" and now - vm["stopped_at"] > 72 * H:
            act(now, vm, "terminate", "stopped for over 72 h")
        elif "asg" in tags and now - vm["launched"] > 24 * H:
            act(now, vm, "recycle", "warm VM older than 24 h")

def act(now, vm, action, why):
    vm["state"] = "terminated"
    print(f"t={now:6.2f}h  {action:9} {vm['id']:6} {why}")

vms = [
    {"id": "warm-1", "state": "stopped", "launched": 0, "stopped_at": 0.5, "tags": {"asg": "lite"}},
    {"id": "run-a",  "state": "running", "launched": 1, "stopped_at": None, "tags": {"run-id": "run-a", "lease-until": 3}},
    {"id": "crash",  "state": "running", "launched": 2, "stopped_at": None, "tags": {"run-id": "crash", "lease-until": 4}},
    # parked at 10h while waiting for a person: stopped, lease set to now + 73 h
    {"id": "parked", "state": "stopped", "launched": 5, "stopped_at": 10, "tags": {"run-id": "parked", "lease-until": 83}},
]

def renew(now):  # the live run renews its lease every 5 minutes; the crashed one stopped at 2.5 h
    for vm in vms:
        if vm["id"] == "run-a" and vm["state"] == "running":
            vm["tags"]["lease-until"] = now + 2
        if vm["id"] == "crash" and now < 2.5 and vm["state"] == "running":
            vm["tags"]["lease-until"] = now + 2

RETIRE_DELAY = 0.5  # the orchestrator's worker was restarting, so the 72 h timer's activity starts 30 minutes late

def retire(now):  # Temporal: 72 h after parking, start the VM, checkpoint, then terminate it
    vm = next(v for v in vms if v["id"] == "parked")
    if abs(now - (vm["stopped_at"] + 72 * H + RETIRE_DELAY)) < 0.01:
        if vm["state"] == "terminated":
            print(f"t={now:6.2f}h  retire    parked FAILED: the VM is already gone, nothing was checkpointed")
        else:
            vm["state"] = "terminated"
            print(f"t={now:6.2f}h  retire    parked checkpoint pushed, then terminated by the workflow")

t = 0.0
while t <= 90:
    renew(t)
    retire(t)
    sweep(t, vms)
    t += 0.25  # every 15 minutes
print("still alive:", [vm["id"] for vm in vms if vm["state"] != "terminated"])
EOF

